solution.solution.cpp:
#include <algorithm>
#include <string>
#include <vector>

struct Input { bool left; bool right; bool pausePressed; };
struct Game { float x{ 100 }; bool paused{ false }; int frames{ 0 }; };

void update(Game& g, const Input& in)
{
    if (in.pausePressed) g.paused = !g.paused;
    if (g.paused) return;
    if (in.right) g.x += 4.0f;
    if (in.left) g.x -= 4.0f;
    g.x = std::clamp(g.x, 0.0f, 750.0f);
    ++g.frames;
}

std::vector<std::string> draw(const Game& g)
{
    std::vector<std::string> calls{ "clear RAYWHITE", "rect " + std::to_string(static_cast<int>(g.x)) + " 200 50 50", "text frames " + std::to_string(g.frames) };
    if (g.paused) calls.push_back("text PAUSED");
    return calls;
}

unitTests:
using Calls = std::vector<std::string>;
TEST("moving") { Game g; update(g, { false, true, false }); update(g, { false, true, false }); CHECK_NEAR(g.x, 108.0, 1e-4); CHECK_EQ(g.frames, 2); update(g, { true, true, false }); CHECK_NEAR(g.x, 108.0, 1e-4); }
TEST("clamped") { Game g; g.x = 2; update(g, { true, false, false }); CHECK_NEAR(g.x, 0.0, 1e-4); g.x = 748; update(g, { false, true, false }); CHECK_NEAR(g.x, 750.0, 1e-4); }
TEST("pause freezes everything") {
    Game g; update(g, { false, false, true }); CHECK(g.paused); CHECK_EQ(g.frames, 0);
    update(g, { false, true, false }); CHECK_NEAR(g.x, 100.0, 1e-4); CHECK_EQ(g.frames, 0);
    update(g, { false, true, true }); CHECK(!g.paused); CHECK_NEAR(g.x, 104.0, 1e-4); CHECK_EQ(g.frames, 1);
}
TEST("draw calls") {
    Game g; g.x = 123.9f; g.frames = 7;
    CHECK_EQ(draw(g), (Calls{ "clear RAYWHITE", "rect 123 200 50 50", "text frames 7" }));
    g.paused = true; CHECK_EQ(draw(g).back(), std::string("text PAUSED")); CHECK_EQ(draw(g).size(), std::size_t{ 4 });
}

